// Fixture: MCP server with 600 programmatically generated tools.
import { createInterface } from "node:readline";
export const tools = Array.from({length:600},(_,i)=>({name:`tool_${String(i).padStart(3,"0")}`,description:`Generated tool number ${i} that performs operation ${i} for validation of large tool lists.`,inputSchema:{type:"object",properties:{input:{type:"string",description:`Input value for operation ${i}.`}},required:["input"]}}));
const rl=createInterface({input:process.stdin});
rl.on("line",(line)=>{let msg;try{msg=JSON.parse(line)}catch{return} const reply=(o)=>process.stdout.write(JSON.stringify(o)+"\n"); if(msg.method==="initialize"){reply({jsonrpc:"2.0",id:msg.id,result:{protocolVersion:"2024-11-05",capabilities:{tools:{}},serverInfo:{name:"fixture-huge",version:"1.0.0"}}})}else if(msg.method==="ping"){reply({jsonrpc:"2.0",id:msg.id,result:{}})}else if(msg.method==="tools/list"){reply({jsonrpc:"2.0",id:msg.id,result:{tools}})}else if(msg.method==="tools/call"){const found=tools.find(t=>t.name===msg.params?.name); if(!found)reply({jsonrpc:"2.0",id:msg.id,error:{code:-32602,message:`Unknown tool: ${msg.params?.name}`}}); else reply({jsonrpc:"2.0",id:msg.id,result:{content:[{type:"text",text:"ok"}]}})}else if(msg.id!==undefined){reply({jsonrpc:"2.0",id:msg.id,error:{code:-32601,message:`Method not found: ${msg.method}`}})}});
